import static org.mockito.Mockito.*;

public class BasicSerializerFactory_buildContainerSerializer_TriageGen2Test {

    private BasicSerializerFactory factory;
    private SerializerProvider prov;
    private SerializationConfig config;
    private BeanDescription beanDesc;
    private TypeFactory typeFactory;

    // Concrete implementation of BasicSerializerFactory to test protected method
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        private final Serializers customSerializers;

        public TestableBasicSerializerFactory(SerializerFactoryConfig config, Serializers customSerializers) {
            super(config);
            this.customSerializers = customSerializers;
        }

        @Override
        protected Iterable<Serializers> customSerializers() {
            return customSerializers;
        }

        // Mocking internal build methods to avoid deep recursion/complex setup
        @Override
        protected JsonSerializer<?> buildMapSerializer(SerializationConfig config, MapType type, BeanDescription beanDesc, boolean staticTyping, JsonSerializer<Object> keySerializer, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }

        @Override
        protected JsonSerializer<?> buildCollectionSerializer(SerializationConfig config, CollectionType type, BeanDescription beanDesc, boolean staticTyping, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }

        @Override
        protected JsonSerializer<?> buildArraySerializer(SerializationConfig config, ArrayType type, BeanDescription beanDesc, boolean staticTyping, TypeSerializer elementTypeSerializer, JsonSerializer<Object> elementValueSerializer) {
            return mock(JsonSerializer.class);
        }

        // Expose protected method for testing
        public JsonSerializer<?> publicBuildContainerSerializer(SerializerProvider prov, JavaType type, BeanDescription beanDesc, boolean staticTyping) throws JsonMappingException {
            return super.buildContainerSerializer(prov, type, beanDesc, staticTyping);
        }

        // Mocking these to control flow
        @Override
        public TypeSerializer createTypeSerializer(SerializationConfig config, JavaType baseType) {
            return null; 
        }

        @Override
        protected JsonSerializer<Object> _findKeySerializer(SerializerProvider prov, com.fasterxml.jackson.databind.introspect.Annotated a) {
            return null;
        }

        @Override
        protected JsonSerializer<Object> _findContentSerializer(SerializerProvider prov, com.fasterxml.jackson.databind.introspect.Annotated a) {
            return null;
        }
    }

    @Before
    public void setUp() {
        prov = mock(SerializerProvider.class);
        config = mock(SerializationConfig.class);
        beanDesc = mock(BeanDescription.class);
        typeFactory = TypeFactory.defaultInstance();
        when(prov.getConfig()).thenReturn(config);
        factory = new TestableBasicSerializerFactory(mock(SerializerFactoryConfig.class), Collections.emptyList());
    }

    @Test
    public void testBuildContainerSerializer_ArrayType() throws JsonMappingException {
        JavaType arrayType = typeFactory.constructArrayType(String.class);
        JsonSerializer<?> result = factory.publicBuildContainerSerializer(prov, arrayType, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testBuildContainerSerializer_TrueMapType() throws JsonMappingException {
        JavaType mapType = typeFactory.constructMapType(java.util.Map.class, String.class, Integer.class);
        JsonSerializer<?> result = factory.publicBuildContainerSerializer(prov, mapType, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testBuildContainerSerializer_TrueCollectionType() throws JsonMappingException {
        JavaType collType = typeFactory.constructCollectionType(java.util.List.class, String.class);
        JsonSerializer<?> result = factory.publicBuildContainerSerializer(prov, collType, beanDesc, false);
        assertNotNull(result);
    }

    @Test
    public void testBuildContainerSerializer_StaticTypingLogic_ForceStatic() throws JsonMappingException {
        // Test logic: if (!staticTyping && type.useStaticType()) ...
        // We need a type that returns useStaticType() = true and is a container
        JavaType type = mock(JavaType.class);
        when(type.useStaticType()).thenReturn(true);
        when(type.isContainerType()).thenReturn(true);
        when(type.getContentType()).thenReturn(typeFactory.constructType(String.class));
        when(type.isMapLikeType()).thenReturn(false);
        when(type.isCollectionLikeType()).thenReturn(false);
        when(type.isArrayType()).thenReturn(true);

        // If we pass staticTyping = false, it should be forced to true internally
        // Since we can't easily check the internal 'staticTyping' variable, we rely on the branch coverage
        factory.publicBuildContainerSerializer(prov, type, beanDesc, false);
        verify(type, atLeastOnce()).useStaticType();
    }

    @Test
    public void testBuildContainerSerializer_CustomMapLikeSerializer() throws JsonMappingException {
        JavaType mapType = typeFactory.constructMapType(java.util.HashMap.class, String.class, String.class);

        Serializers customSerializers = mock(Serializers.class);
        JsonSerializer<Object> customSer = new StdSerializer<Object>(Object.class) {
            @Override public void serialize(Object value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {}
        };

        when(customSerializers.findMapLikeSerializer(any(), any(), any(), any(), any(), any())).thenReturn(customSer);

        TestableBasicSerializerFactory factoryWithCustom = new TestableBasicSerializerFactory(
                factory.getFactoryConfig(), 
                Collections.singletonList(customSerializers)
        );

        JsonSerializer<?> result = factoryWithCustom.publicBuildContainerSerializer(prov, mapType, beanDesc, false);
        assertEquals(customSer, result);
    }

    @Test
    public void testBuildContainerSerializer_CustomCollectionLikeSerializer() throws JsonMappingException {
        JavaType collType = typeFactory.constructCollectionType(java.util.ArrayList.class, String.class);

        Serializers customSerializers = mock(Serializers.class);
        JsonSerializer<Object> customSer = new StdSerializer<Object>(Object.class) {
            @Override public void serialize(Object value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {}
        };

        when(customSerializers.findCollectionLikeSerializer(any(), any(), any(), any(), any())).thenReturn(customSer);

        TestableBasicSerializerFactory factoryWithCustom = new TestableBasicSerializerFactory(
                factory.getFactoryConfig(), 
                Collections.singletonList(customSerializers)
        );

        JsonSerializer<?> result = factoryWithCustom.publicBuildContainerSerializer(prov, collType, beanDesc, false);
        assertEquals(customSer, result);
    }

    @Test
    public void testBuildContainerSerializer_WithSerializerModifier() throws JsonMappingException {
        JavaType mapType = typeFactory.constructMapType(java.util.HashMap.class, String.class, String.class);

        Serializers customSerializers = mock(Serializers.class);
        JsonSerializer<Object> customSer = new StdSerializer<Object>(Object.class) {
            @Override public void serialize(Object value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) {}
        };
        when(customSerializers.findMapLikeSerializer(any(), any(), any(), any(), any(), any())).thenReturn(customSer);

        BeanSerializerModifier modifier = mock(BeanSerializerModifier.class);
        JsonSerializer<Object> modifiedSer = mock(JsonSerializer.class);
        when(modifier.modifyMapLikeSerializer(any(), any(), any(), any())).thenReturn(modifiedSer);

        SerializerFactoryConfig configWithMod = mock(SerializerFactoryConfig.class);
        when(configWithMod.hasSerializerModifiers()).thenReturn(true);
        when(configWithMod.serializerModifiers()).thenReturn(Collections.singletonList(modifier));

        TestableBasicSerializerFactory factoryWithMod = new TestableBasicSerializerFactory(configWithMod, Collections.singletonList(customSerializers));

        JsonSerializer<?> result = factoryWithMod.publicBuildContainerSerializer(prov, mapType, beanDesc, false);
        assertEquals(modifiedSer, result);
    }

    @Test
    public void testBuildContainerSerializer_NullReturns() throws JsonMappingException {
        // Test a type that is none of the above
        JavaType nonContainerType = typeFactory.constructType(Integer.class);
        JsonSerializer<?> result = factory.publicBuildContainerSerializer(prov, nonContainerType, beanDesc, false);
        assertNull(result);
    }

    @Test
    public void testBuildContainerSerializer_ElementTypeSerializerFound() throws JsonMappingException {
        // If elementTypeSerializer != null, staticTyping = false
        JavaType type = mock(JavaType.class);
        JavaType contentType = typeFactory.constructType(String.class);
        when(type.isContainerType()).thenReturn(true);
        when(type.getContentType()).thenReturn(contentType);
        when(type.isMapLikeType()).thenReturn(false);
        when(type.isCollectionLikeType()).thenReturn(false);
        when(type.isArrayType()).thenReturn(false);

        // Create a specialized factory to return a TypeSerializer
        TestableBasicSerializerFactory factoryWithTypeSer = new TestableBasicSerializerFactory(factory.getFactoryConfig(), Collections.emptyList()) {
            @Override
            public TypeSerializer createTypeSerializer(SerializationConfig config, JavaType baseType) {
                return mock(TypeSerializer.class);
            }
        };

        factoryWithTypeSer.publicBuildContainerSerializer(prov, type, beanDesc, true);
        // Branch coverage for if (elementTypeSerializer != null)
    }
}
